    listBookDocuments_v2: {
        parameters: {
            query: {
                /** @description ID de la entidad maestra. El public ID de la entidad (`ment_...`). */
                master_entity_id: string;
                /** @description Período tributario a consultar, formato YYYYMM. Es el período en que el SII clasifica el documento en ese libro, que puede diferir del mes de emisión. */
                period: string;
                /** @description Libro a consultar: `COMPRA` (la entidad es el receptor, libro de compras) o `VENTA` (la entidad es el emisor, libro de ventas). */
                operation: "COMPRA" | "VENTA";
                /** @description Filtra por tipo de documento SII. Lista separada por coma, por ejemplo `33,61`. */
                dte_type_code?: string;
                /** @description Página (desde 1). */
                page?: number;
                /** @description Filas por página. Por defecto 25, máximo 100. */
                page_size?: number;
            };
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description Filas del libro para la entidad, período y operación consultados */
            200: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        data?: components["schemas"]["BookDocumentItem"][];
                        meta?: {
                            page?: number | null;
                            page_size?: number | null;
                            total?: number;
                            total_pages?: number | null;
                            /** @description true si la entidad tiene habilitado el scrape del libro consultado (PURCHASE_BOOK para COMPRA, SALE_BOOK para VENTA). Si es false, `data` estará vacío aunque el período sea válido. */
                            is_enabled?: boolean;
                        };
                        links?: {
                            next?: string | null;
                            prev?: string | null;
                        };
                    };
                };
            };
            /** @description master_entity_id, period u operation faltantes o inválidos, o dte_type_code mal formado */
            400: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        /** @example operation is required: COMPRA or VENTA. */
                        error?: string;
                    };
                };
            };
            /** @description Sin acceso a la entidad, o la API key no tiene el permiso book_summary:access */
            403: {
                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        /** @example Access denied. */
                        error?: string;
                    };
                };
            };
        };
    };
